import{_ as t,o,c as r,a2 as n}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"ADR-083 — Mobile runtime environment switcher (internal builds only; release is prod-locked)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-083.md","filePath":"adr/ADR-083.md"}'),i={name:"adr/ADR-083.md"};function a(s,e,d,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-083-—-mobile-runtime-environment-switcher-internal-builds-only-release-is-prod-locked" tabindex="-1">ADR-083 — Mobile runtime environment switcher (internal builds only; release is prod-locked) <a class="header-anchor" href="#adr-083-—-mobile-runtime-environment-switcher-internal-builds-only-release-is-prod-locked" aria-label="Permalink to &quot;ADR-083 — Mobile runtime environment switcher (internal builds only; release is prod-locked)&quot;">​</a></h1><blockquote><p>Status · <strong>Accepted — implemented + verified end-to-end on iOS simulator AND Android emulator (2026-07-25).</strong> Built: <code>src/lib/target-env.ts</code> (+ tests), <code>__MOBILE_INTERNAL__</code> define, asset-url/sentry/analytics wiring, <code>TargetEnvSwitcher.svelte</code>, and <code>reconcilePrerenderedAssetOrigins()</code> (see below). Verified via the real WebView inspectors (iOS WebKit <code>ios-webkit-debug-proxy</code>; Android Chrome DevTools Protocol): default = <strong>staging</strong> (Umami <code>6e7ddfce</code>, assets <code>chipi.github.io</code>, analytics POST → 200); real button tap → <code>localStorage.targetEnv=&#39;prod&#39;</code>; relaunch → <strong>prod</strong> (Umami <code>4a25d8da</code>, assets <code>www.orrerylearn.com</code>, analytics POST → 200). <code>@sentry/capacitor</code> native crash reporting active on both (logcat breadcrumbs) — sends via the native transport (not a WebView fetch), so it follows the same <code>targetConfig()</code> tier by construction.</p><p><strong>Findings during verification:</strong> (1) the prerendered landing hero did NOT switch — <code>assetOrigin</code> is a module const baked into prerendered HTML and Svelte doesn&#39;t re-evaluate a non-reactive const on hydration (client-navigated pages were already correct). Fixed with an internal-only <code>reconcilePrerenderedAssetOrigins()</code> called from the layout mount, which rewrites prerendered image origins to the active tier. (2) <strong>localStorage flush nuance:</strong> iOS <code>simctl terminate</code> flushes WKWebView storage cleanly so the flip persists; Android <code>am force-stop</code> kills the process <em>before</em> the WebView flushes, losing the flip — a real relaunch backgrounds first (<code>onPause</code> → flush), which persists it. Test/verify accordingly. Date · 2026-07-24 Related ADRs · ADR-082 (telemetry env ladder — the tiers this switches between), ADR-079 (<code>assetUrl</code> origin spine / <code>STREAM_ORIGIN</code>), ADR-078 (mobile stream-heavy bundle), ADR-016 (no client storage — the carve-out this reuses)</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-082 made the mobile app a <em>segment</em> of the dev→staging→prod ladder, with the tier <strong>baked at build time</strong> (<code>PUBLIC_SENTRY_*</code> / <code>PUBLIC_UMAMI_*</code> / <code>STREAM_ORIGIN</code> via Vite <code>define</code>). To switch what a build targets you must <strong>rebuild + reinstall</strong>. For a testing loop that is too slow: the operator wants to flip an installed app between <strong>staging</strong> and <strong>prod</strong> on the fly to see whether observability + content land in the right place — without a rebuild.</p><p>But a runtime switch must never reach an App Store user: flipping a shipped app to staging/dev would pollute the prod dataset and expose internal endpoints.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Internal builds</strong> (simulator / TestFlight / any non-release) ship a <strong>runtime &quot;target environment&quot; switcher</strong>. <strong>App Store release builds are prod-locked</strong> — no switcher, only prod config baked. One selection moves <strong>all three</strong> coupled concerns together, so &quot;target = staging&quot; means one coherent thing:</p><table tabindex="0"><thead><tr><th>The switch repoints</th><th>Staging</th><th>Prod</th></tr></thead><tbody><tr><td><strong>Asset / image + locale streaming</strong> (<code>STREAM_ORIGIN</code>, ADR-079)</td><td><code>chipi.github.io/orrery</code></td><td><code>orrerylearn.com</code></td></tr><tr><td><strong>Sentry</strong> (DSN → project, <code>environment</code>)</td><td>project 6 · <code>environment=staging</code></td><td>project 4 · <code>environment=prod</code></td></tr><tr><td><strong>Umami</strong> (<code>PUBLIC_UMAMI_WEBSITE_ID</code>)</td><td>staging site</td><td>prod site</td></tr></tbody></table><p>On-device tiers are <strong>staging + prod only — NOT dev.</strong> The dev tier lives on the tailnet host <code>homelab</code> (ADR-082), which a device/simulator off the tailnet can&#39;t resolve; dev stays a <code>vite dev</code>-in-browser concern.</p><h2 id="design-spec-for-the-ios-thread" tabindex="-1">Design (spec for the iOS thread) <a class="header-anchor" href="#design-spec-for-the-ios-thread" aria-label="Permalink to &quot;Design (spec for the iOS thread)&quot;">​</a></h2><ul><li><strong>Build flag <code>__MOBILE_INTERNAL__</code></strong> (new Vite <code>define</code>, set by an env var at build like <code>STREAM_ORIGIN</code>): <code>true</code> for internal/simulator/TestFlight builds, <code>false</code> for App Store release. It is the single gate.</li><li><strong>Config shape:</strong><ul><li><em>Internal build</em> bakes an <strong>all-tier config map</strong> — <code>{ staging: {origin, sentryDsn, sentryEnv, umamiId}, prod: {…} }</code> — plus the switcher UI.</li><li><em>Release build</em> (<code>__MOBILE_INTERNAL__ === false</code>) bakes <strong>only prod</strong> as a single constant; the switcher code + staging config are tree-shaken out. An App Store user has no path to another tier.</li></ul></li><li><strong>Selection storage:</strong> a <code>localStorage</code> key <code>orrery.targetEnv</code> (<code>&#39;staging&#39; | &#39;prod&#39;</code>), reusing the ADR-016 client-storage carve-out already set by <code>orrery.qualityTier</code> — <strong>no new dependency</strong> (<code>@capacitor/preferences</code> is an alternative but would need approval). Default for internal builds: <strong>staging</strong> (safe sandbox); release is hard-<code>prod</code>.</li><li><strong>What reads the selection:</strong><ul><li><code>assetUrl.ts</code> (ADR-079 spine): <code>resolveAssetOrigin</code> / <code>resolveStreamedUrl</code> / <code>resolveLocaleBundleOrigin</code> resolve the <strong>active</strong> origin from <code>orrery.targetEnv</code> instead of the single baked <code>STREAM_ORIGIN</code>, when <code>__MOBILE_INTERNAL__</code>.</li><li><code>sentry.ts</code> / <code>analytics.ts</code>: read the active tier&#39;s DSN/env/umami-id from the map.</li></ul></li><li><strong>Re-init on switch:</strong><ul><li>Telemetry JS layer re-inits cleanly with the new config.</li><li><strong>Caveat — native crash sink:</strong> <code>@sentry/capacitor</code> native handlers init once at startup; a runtime flip moves the JS/web-layer reporting immediately, but the <strong>native</strong> sink likely needs an <strong>app relaunch</strong> to fully rebind. The switcher should say &quot;relaunch to fully apply native crash routing.&quot; (Verify on-device.)</li><li>Assets already loaded + SW-cached under the old origin stay cached; new fetches use the new origin. Note for testing (a hard reload / cache clear may be wanted).</li></ul></li><li><strong>UI:</strong> a control in the in-app DebugPanel (<code>?debug=1</code>) or a dedicated internal settings row — rendered only when <code>__MOBILE_INTERNAL__</code>.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Build-time per tier (no in-app switch)</strong> — rejected: the rebuild+reinstall loop is exactly the friction that motivated this. (It remains the fallback and is what ADR-082 already supports.)</li><li><strong>Runtime switch in the release build too</strong> — rejected: an App Store user could flip to staging/dev, polluting prod data and exposing internal endpoints.</li><li><strong><code>@capacitor/preferences</code> for storage</strong> — deferred: a new dep for a value <code>localStorage</code> already handles under the existing ADR-016 carve-out.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Internal builds carry all-tier <strong>public</strong> DSN/site-ids (safe — they ship in any bundle by design). Release carries only prod.</li><li>Touches: <code>vite.config.ts</code> (the <code>__MOBILE_INTERNAL__</code> define + all-tier config injection), <code>asset-url.ts</code>, <code>sentry.ts</code>, <code>analytics.ts</code>, and a new switcher UI.</li><li>Implementation is deferred to the iOS thread (needs Xcode + a device to prove the native re-bind + real cross-tier routing). No GitHub issue opened without operator approval — tracked here + in the mobile guide until then.</li></ul><h2 id="not-covered-out-of-scope" tabindex="-1">Not covered / out of scope <a class="header-anchor" href="#not-covered-out-of-scope" aria-label="Permalink to &quot;Not covered / out of scope&quot;">​</a></h2><ul><li>The dev tier on-device (unreachable off-tailnet — staging/prod only here).</li><li>Native crash <em>symbolication</em> (App Store Connect / Play Console — ADR-082 amendment / the #428 note).</li></ul>',17)])])}const p=t(i,[["render",a]]);export{u as __pageData,p as default};
